1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { Icon } from "./Icon";
6	import { PageShell, Panel, StatCard } from "./PageShell";
7	import { CATEGORIES, categoryMeta, titleOf } from "@/lib/nx/activity";
8	
9	type Event = {
10	  id: string; action: string; category: string;
11	  detail: string; target: string; ip: string; at: string;
12	};
13	
14	/** "12 min ago" — the concept's relative column, with the exact time beside it. */
15	/* Both of the strings this file derives from a timestamp are hydration
16	   hazards, and BOTH were firing (React #418 on /dashboard/activity):
17	
18	     - `ago()` reads Date.now(), so the server can say "5 min ago" and the
19	       client "6 min ago" a moment later;
20	     - the absolute stamp below passes `undefined` as the locale, which
21	       resolves to Node's on the server and the browser's on the client.
22	
23	   Neither is wrong to show — the client's answer is the CORRECT one in both
24	   cases — so the fix is to tell React the difference is expected rather than
25	   to freeze the output to a locale and clock the reader does not have.
26	   suppressHydrationWarning is exactly the escape hatch for this, and it only
27	   covers the text directly inside the element it is set on. */
28	function ago(iso: string): string {
29	  const s = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
30	  if (s < 60) return "just now";
31	  const m = Math.round(s / 60);
32	  if (m < 60) return `${m} min ago`;
33	  const h = Math.round(m / 60);
34	  if (h < 24) return `${h} hour${h === 1 ? "" : "s"} ago`;
35	  const d = Math.round(h / 24);
36	  return `${d} day${d === 1 ? "" : "s"} ago`;
37	}
38	
39	export function ActivityView({
40	  who, days, events, counts, total, prevTotal, sessions, sessionsTracked,
41	}: {
42	  who: string; days: number; events: Event[];
43	  counts: Record<string, number>; total: number; prevTotal: number;
44	  sessions: number; sessionsTracked: boolean;
45	}) {
46	  const router = useRouter();
47	  const [picked, setPicked] = useState<Set<string>>(new Set());
48	  const [q, setQ] = useState("");
49	
50	  const shown = useMemo(() => {
51	    const needle = q.trim().toLowerCase();
52	    return events.filter((e) =>
53	      (picked.size === 0 || picked.has(e.category)) &&
54	      (!needle ||
55	        titleOf(e.action).toLowerCase().includes(needle) ||
56	        e.detail.toLowerCase().includes(needle) ||
57	        e.target.toLowerCase().includes(needle)));
58	  }, [events, picked, q]);
59	
60	  /* Only compare where there is something to compare against. From a period
61	     with no activity, any percentage is division by zero dressed up. */
62	  const delta = prevTotal > 0 ? Math.round(((total - prevTotal) / prevTotal) * 100) : null;
63	  const serverCount = counts.server ?? 0;
64	  const billingCount = counts.billing ?? 0;
65	
66	  const toggle = (key: string) =>
67	    setPicked((prev) => {
68	      const next = new Set(prev);
69	      next.has(key) ? next.delete(key) : next.add(key);
70	      return next;
71	    });
72	
73	  return (
74	    <PageShell eyebrow="Activity" title="All your activity"
75	               sub={`Everything that happened on your account in the last ${days} days, newest first.`}
76	               tagline={["TRANSPARENT.", "SECURE.", "ALWAYS ON."]}>
77	      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
78	        <StatCard icon="activity" value={String(total)} label="Events"
79	                  foot={delta !== null
80	                    ? <span className={"text-[11px] font-bold " + (delta >= 0 ? "text-mint" : "text-rose")}>
81	                        {delta >= 0 ? "+" : ""}{delta}% vs previous {days} days
82	                      </span>
83	                    : <span className="text-[11px] text-tx-faint">No earlier period to compare</span>} />
84	        <StatCard icon="server" value={String(serverCount)} label="Server actions" tone="violet" />
85	        <StatCard icon="card" value={String(billingCount)} label="Billing events" tone="mint" />
86	        <StatCard icon="user" value={sessionsTracked ? String(sessions) : "—"} label="Sign-ins" tone="amber"
87	                  foot={!sessionsTracked
88	                    /* Never 0 — zero would claim nobody signed in, when the
89	                       truth is that sessions are not being recorded yet. */
90	                    ? <span className="text-[11px] text-tx-faint">Not being recorded yet</span>
91	                    : undefined} />
92	      </div>
93	
94	      <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_280px]">
95	        <Panel title="Activity log" sub={`${shown.length} of ${total} shown`}
96	               action={
97	                 <span className="field h-[34px] w-[190px]">
98	                   <Icon name="search" size={14} />
99	                   <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search"
100	                          className="min-w-0 flex-1 bg-transparent text-[12px] text-white outline-none placeholder:text-tx-faint" />
101	                 </span>
102	               }>
103	          {shown.length === 0 ? (
104	            <span className="py-8 text-center text-[11.8px] text-tx-faint">
105	              {total === 0 ? "Nothing recorded in this period." : "No events match these filters."}
106	            </span>
107	          ) : (
108	            <ul className="flex flex-col">
109	              {shown.slice(0, 120).map((e) => {
110	                const meta = categoryMeta(e.category);
111	                return (
112	                  <li key={e.id} className="flex items-start gap-3 border-b border-rim-soft py-2.5 last:border-0">
113	                    <span className="grid h-[30px] w-[30px] flex-none place-items-center rounded-[9px] border border-rim-hi bg-well"
114	                          style={{ boxShadow: `inset 0 0 0 1px ${meta.tone}33` }}>
115	                      <Icon name={meta.icon} size={14} />
116	                    </span>
117	                    <span className="flex min-w-0 flex-1 flex-col">
118	                      <span className="trunc text-[12.5px] font-semibold text-white">{titleOf(e.action)}</span>
119	                      <span className="trunc text-[11px] text-tx-faint">
120	                        {[e.target, e.detail].filter(Boolean).join(" · ") || meta.label}
121	                      </span>
122	                    </span>
123	                    {e.ip && <span className="mono hidden flex-none text-[10.8px] text-tx-faint sm:block">{e.ip}</span>}
124	                    <span className="flex flex-none flex-col items-end">
125	                      <span suppressHydrationWarning className="text-[11px] text-tx-dim">{ago(e.at)}</span>
126	                      <span suppressHydrationWarning className="hidden text-[10.5px] text-tx-faint sm:block">
127	                        {new Date(e.at).toLocaleString(undefined, { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}
128	                      </span>
129	                    </span>
130	                  </li>
131	                );
132	              })}
133	            </ul>
134	          )}
135	        </Panel>
136	
137	        <div className="flex min-w-0 flex-col gap-3">
138	          <Panel title="Period">
139	            <div className="flex gap-1.5">
140	              {[7, 30, 90].map((d) => (
141	                <button key={d} type="button"
142	                        onClick={() => router.push(`/dashboard/activity?days=${d}`)}
143	                        className={"chip h-[30px] flex-1 justify-center px-2 text-[12px] " + (days === d ? "chip-on" : "")}>
144	                  {d}d
145	                </button>
146	              ))}
147	            </div>
148	          </Panel>
149	
150	          <Panel title="Categories"
151	                 action={picked.size > 0
152	                   ? <button type="button" onClick={() => setPicked(new Set())}
153	                             className="text-[11.5px] font-semibold text-cyan hover:text-white">Reset</button>
154	                   : undefined}>
155	            <ul className="flex flex-col">
156	              {CATEGORIES.map((c) => {
157	                const n = counts[c.key] ?? 0;
158	                const on = picked.has(c.key);
159	                return (
160	                  <li key={c.key}>
161	                    <button type="button" onClick={() => toggle(c.key)} disabled={n === 0}
162	                            className={"flex w-full items-center gap-2.5 rounded-[8px] px-1.5 py-1.5 text-left transition-colors " +
163	                              (on ? "bg-[rgba(72,148,255,0.10)]" : "hover:bg-[rgba(72,148,255,0.06)]") +
164	                              (n === 0 ? " opacity-40" : "")}>
165	                      <span className="h-[9px] w-[9px] flex-none rounded-[3px]"
166	                            style={{ background: on ? c.tone : "transparent", border: `1px solid ${c.tone}` }} />
167	                      <Icon name={c.icon} size={14} className="flex-none opacity-85" />
168	                      <span className="trunc flex-1 text-[12px] text-tx-body">{c.label}</span>
169	                      <span className="flex-none text-[11px] font-bold text-tx-faint">{n}</span>
170	                    </button>
171	                  </li>
172	                );
173	              })}
174	            </ul>
175	          </Panel>
176	
177	          <Panel title="About this log">
178	            <span className="text-[11.8px] leading-[1.5] text-tx-mute">
179	              Every action taken on {who}&apos;s account is recorded here — by you, by our staff,
180	              and by the system. Entries cannot be edited or removed.
181	            </span>
182	          </Panel>
183	        </div>
184	      </div>
185	    </PageShell>
186	  );
187	}
